p + '|record|' + id + '|' + payload);\n  const seal = { id: state.chain.length + 1, kind: 'record', ref: String(id), payload, prev_hash: tip, hash };\n  if (identityActive(state.chain)) {\n    if (!signingKeyHex) return { ok: false, reason: 'IDENTITY ACTIVE — sealed write requires a signing key' };\n    const sg = sealSignature(seal, signingKeyHex);\n    seal.sig = sg.sig; seal.sig_by = sg.sig_by;\n  }\n  const newState = { records: state.records.concat([rec]), chain: state.chain.concat([seal]) };\n  return { ok: true, record: rec, seal, state: newState, digest: await digestOf(newState, uiManifest, codeManifest) };\n}\n\nasync function ingestReturn(sourceState, uiManifest, codeManifest, survivorExport) {\n  const fail = (verdict) => ({ ok: false, verdict });\n  const ANCHOR_URLS = ['https://raw.githubusercontent.com/rabiuhamza11/harz-survivor/main/anchors/ledger.md', 'https://cdn.jsdelivr.net/gh/rabiuhamza11/harz-survivor@main/anchors/ledger.md', 'https://raw.githack.com/rabiuhamza11/harz-survivor/main/anchors/ledger.md'];\n  if (!survivorExport || !survivorExport.state) return fail('BROKEN — malformed survivor export');\n  const sChain = survivorExport.state.chain || [];\n  const marker = activeMarker(sChain);\n  if (!marker) return fail('BROKEN — no active walkout marker in survivor export');\n  const srcChain = sourceState.chain || [];\n  let mi = -1;\n  for (let i = 0; i < srcChain.length; i++) if (srcChain[i].hash === marker.hash) { mi = i; break; }\n  if (mi === -1) return fail('BROKEN — marker mismatch: not my walkout');\n  const postMarker = srcChain.slice(mi + 1);\n  const bookSeals = postMarker.filter(s => s.kind !== 'code_pin' && s.kind !== 'ui_manifest');\n  if (bookSeals.length) return fail('FORK DETECTED — source has post-marker book seals');\n  const baseRecords = sourceState.records || [];\n  const allRecords = survivorExport.state.records || [];\n  if (allRecords.length < baseRecords.length) return fail('BROKEN — base records missing');\n  for (let i = 0; i < baseRecords.length; i++) {\n    const a = baseRecords[i], b = allRecords[i];\n    if (String(a.id) !== String(b.id) || a.body !== b.body || a.created !== b.created)\n      return fail('BROKEN — base records rewritten');\n  }\n  let mIdx = -1;\n  for (let i = 0; i < sChain.length; i++) if (sChain[i].hash === marker.hash) { mIdx = i; break; }\n  const overlay = sChain.slice(mIdx + 1);\n  const overlayRecords = allRecords.slice(baseRecords.length);\n  const composed = srcChain.slice(0, mi + 1).concat(overlay);\n  const v = await verifyChain(composed);\n  if (!v.ok) return fail('BROKEN — overlay does not chain from the marker: ' + v.issues.join('; '));\n  const baseDigest = await digestOf(sourceState, uiManifest, codeManifest);\n  let ledger = null, servedFrom = null, anyReachable = false;\n  for (const u of ANCHOR_URLS) {\n    try {\n      const res = await fetch(u, { cache: 'no-store' });\n      if (!res.ok) continue;\n      const text = await res.text();\n      anyReachable = true;\n      if (text.includes(baseDigest)) { ledger = text; servedFrom = u; break; }\n    } catch (e) { continue; }\n  }\n  if (!anyReachable) return fail('BROKEN — ANCHOR UNREACHABLE — return refused fail-closed (all mirrors)');\n  if (!ledger) return fail('BROKEN — ANCHOR MISMATCH — pre-marker base ' + baseDigest.slice(0, 16) + '… not found in any reachable anchored history');\n  const anchorProof = { url: servedFrom, anchored_base: baseDigest, mirrors_tried: ANCHOR_URLS.length };\n  const tip = composed.length ? composed[composed.length - 1].hash : 'GENESIS';\n  const payload = JSON.stringify({ ingested_seals: overlay.length, ingested_records: overlayRecords.length, marker: marker.hash, anchor: anchorProof });\n  const rhash = await sha256hex(tip + '|return|walkout|' + payload);\n  const returnSeal = { id: composed.length + 1, kind: 'return', ref: 'walkout', payload, prev_hash: tip, hash: rhash };\n  const newState = { records: baseRecords.concat(overlayRecords), chain: composed.concat([returnSeal]) };\n  return { ok: true, verdict: 'RETURN COMPLETE — one book, one history, anchor-verified', state: newState, ingested: { seals: overlay.length, records: overlayRecords.length }, digest: await digestOf(newState, uiManifest, codeManifest) };\n}\n\nasync function verifyExport(x) {\n  const issues = [];\n  if (!x || !x.state || !x.ui_manifest || !x.ui || !x.code_manifest || !x.code || !x.digest)\n    return { ok: false, issues: ['malformed export'], verdict: 'BROKEN — malformed export' };\n  const chain = x.state.chain || [];\n  const v = await verifyChain(chain);\n  issues.push(...v.issues);\n  let seenMarker = false;\n  for (const r of chain) {\n    if (r.kind === 'walkout_marker') seenMarker = true;\n    else if (r.kind === 'return' && !seenMarker) issues.push('return seal without walkout marker at ' + r.id);\n  }\n  const uiH = await hashAssets(x.ui);\n  for (const p of Object.keys(x.ui_manifest)) {\n    if (!x.ui[p]) issues.push('missing ui asset ' + p);\n    else if (uiH[p] !== x.ui_manifest[p]) issues.push('ui hash mismatch at ' + p);\n  }\n  const codeH = await hashAssets(x.code);\n  for (const p of Object.keys(x.code_manifest)) {\n    if (!x.code[p]) issues.push('missing code asset ' + p);\n    else if (codeH[p] !== x.code_manifest[p]) issues.push('code hash mismatch at ' + p);\n  }\n  const pinnedUi = [...chain].reverse().find(s => s.kind === 'ui_manifest');\n  if (!pinnedUi) issues.push('no ui_manifest pin in chain');\n  else if (pinnedUi.payload !== JSON.stringify(x.ui_manifest)) issues.push('ui_manifest does not match its chain pin');\n  const pinnedCode = [...chain].reverse().find(s => s.kind === 'code_pin');\n  if (!pinnedCode) issues.push('no code_pin in chain');\n  else if (pinnedCode.payload !== JSON.stringify(x.code_manifest)) issues.push('code_manifest does not match its chain pin');\n  const d = await digestOf(x.state, x.ui_manifest, x.code_manifest);\n  if (d !== x.digest) issues.push('digest mismatch');\n  const ok = issues.length === 0;\n  return {\n    ok,\n    issues,\n    digest: d,\n    writes: activeMarker(chain) ? 'WALKOUT ACTIVE — sealed writes open' : 'WRITES SEALED — no active walkout marker',\n    verdict: ok\n      ? 'CAPSULE VERIFIED — chain intact, records sealed, ui sealed, code sealed, digest matches (v0.9)'\n      : 'BROKEN — ' + issues.join('; ')\n  };\n}\n\nfunction canonical(x) {\n  if (x === null || typeof x !== 'object') return JSON.stringify(x);\n  if (Array.isArray(x)) return '[' + x.map(canonical).join(',') + ']';\n  return '{' + Object.keys(x).sort().map(k => JSON.stringify(k) + ':' + canonical(x[k])).join(',') + '}';\n}\n\nasync function receiveBundle(input) {\n  const b = input && input.bundle, localState = input && input.localState;\n  const localUiManifest = input && input.localUiManifest, localCodeManifest = input && input.localCodeManifest;\n  if (!b || !localState || !localUiManifest || !localCodeManifest) return { ok: false, verdict: 'REFUSED — malformed receive input', zero_ingest: true };\n  const { sig, pub, ...body } = b;\n  if (!sig || !pub || !b.payload || !b.payloadHash || !b.claimedDigest || !b.enginePin || !b.id || !b.from)\n    return { ok: false, verdict: 'REFUSED — unsigned or malformed bundle', zero_ingest: true };\n  // 1. payload integrity\n  if (await sha256hex(canonical(b.payload)) !== b.payloadHash)\n    return { ok: false, verdict: 'REFUSED — payload hash mismatch', zero_ingest: true };\n  // 2. signature — Ed25519 via WebCrypto (portable: Node 20+, Cloudflare, Deno)\n  try {\n    const key = await crypto.subtle.importKey('spki', Uint8Array.from(atob(pub), c => c.charCodeAt(0)), { name: 'Ed25519' }, true, ['verify']);\n    const ok = await crypto.subtle.verify({ name: 'Ed25519' }, key, Uint8Array.from(atob(sig), c => c.charCodeAt(0)), new TextEncoder().encode(canonical(body)));\n    if (!ok) return { ok: false, verdict: 'REFUSED — signature invalid', zero_ingest: true };\n  } catch (e) { return { ok: false, verdict: 'REFUSED — signature check failed: ' + String(e), zero_ingest: true }; }\n  // 3. engine pin — the engine never travels; both seats must hold the same pin\n  if (b.enginePin !== localCodeManifest['/engine.js'])\n    return { ok: false, verdict: 'REFUSED — engine pin mismatch (local ' + String(localCodeManifest['/engine.js']).slice(0, 8) + ' vs bundle ' + String(b.enginePin).slice(0, 8) + ')', zero_ingest: true };\n  // 4. UI manifest parity with my sealed capsule\n  if (canonical(b.payload.ui_manifest) !== canonical(localUiManifest))\n    return { ok: false, verdict: 'REFUSED — ui manifest mismatch vs local sealed capsule', zero_ingest: true };\n  // 5. the received book must verify as a self-consistent capsule, digest claim TRUE\n  const v = await verifyExport(b.payload);\n  if (!v.ok) return { ok: false, verdict: 'REFUSED — sealed verifyExport: ' + v.verdict, zero_ingest: true };\n  if (v.digest !== b.claimedDigest || v.digest !== b.payload.digest)\n    return { ok: false, verdict: 'REFUSED — digest claim mismatch', zero_ingest: true };\n  // 6. fork check — my composed chain must be a PREFIX of the received chain, AND every\n  // local record must be contained byte-identical in the received book (records and seals\n  // grow in pairs; both dimensions are checked so no divergence can slip through either)\n  const mine = localState.chain, theirs = b.payload.state.chain;\n  const mineRec = localState.records, theirsRec = b.payload.state.records;\n  if (mine.length > theirs.length || mineRec.length > theirsRec.length)\n    return { ok: false, verdict: 'FORK DETECTED — local history is longer than the received book; no silent merge, both books unchanged, owner ruling required', zero_ingest: true };\n  for (let i = 0; i < mine.length; i++)\n    if (canonical(mine[i]) !== canonical(theirs[i]))\n      return { ok: false, verdict: 'FORK DETECTED — local chain diverges from the received book at seal ' + mine[i].id + '; no silent merge, both books unchanged, owner ruling required', zero_ingest: true };\n  for (let i = 0; i < mineRec.length; i++)\n    if (canonical(mineRec[i]) !== canonical(theirsRec[i]))\n      return { ok: false, verdict: 'FORK DETECTED — local records diverge from the received book at record ' + mineRec[i].id + '; no silent merge, both books unchanged, owner ruling required', zero_ingest: true };\n  // 7. converged, or adopt with a sealed ingest\n  if (mine.length === theirs.length)\n    return { ok: true, verdict: 'CONVERGED — byte-identical books, nothing written', digest: v.digest, action: 'none' };\n  const tip = theirs[theirs.length - 1].hash;\n  const sealPayload = JSON.stringify({ from: b.from, bundle: b.id, claimed: b.claimedDigest, received_records: b.payload.state.records.length, received_seals: theirs.length, ts: b.ts || null });\n  const sealHash = await sha256hex(tip + '|mesh_ingest|mesh|' + sealPayload);\n  const seal = { id: theirs.length + 1, kind: 'mesh_ingest', ref: 'mesh', payload: sealPayload, prev_hash: tip, hash: sealHash };\n  const newState = { records: b.payload.state.records, chain: theirs.concat([seal]) };\n  const digest = await digestOf(newState, b.payload.ui_manifest, b.payload.code_manifest);\n  return { ok: true, verdict: 'ADOPTED — the book walked in; ingest sealed (one book, one history)', action: 'adopt', state: newState, digest, ingested: { records: b.payload.state.records.length - localState.records.length, seals: theirs.length - mine.length } };\n}\n\n// ============ RUNG 2: DETERMINISTIC STATE RECONCILIATION (HarzNet law, Oct 1 2026, owner \"Do all and leave 3 later\") ============\n// mergeBooks: two verified books that worked apart merge into ONE canonical book.\n// Law: deterministic (same inputs -> same merged book, any seat, any order), fork detection\n// at merge time, explicit verdicts per principle 4 (VERIFIED / CONTRADICTED /\n// INSUFFICIENT_EVIDENCE / UNRESOLVED), merge receipts, replay-safe and exactly-once.\n// Fail-closed: a contradiction or unresolved base NEVER merges silently.\n\nasync function mergeBooks(input) {\n  const ea = input && input.exportA, eb = input && input.exportB;\n  const uiManifest = input && input.uiManifest, codeManifest = input && input.codeManifest;\n  const fail = (verdict, extra) => Object.assign({ ok: false, verdict, zero_merge: true }, extra || {});\n  if (!ea || !eb || !uiManifest || !codeManifest)\n    return fail('INSUFFICIENT_EVIDENCE — merge needs two exports plus the shared manifests');\n  const va = await verifyExport(ea), vb = await verifyExport(eb);\n  if (!va.ok) return fail('UNRESOLVED — book A does not verify: ' + va.verdict);\n  if (!vb.ok) return fail('UNRESOLVED — book B does not verify: ' + vb.verdict);\n  if (canonical(ea.ui_manifest) !== canonical(eb.ui_manifest))\n    return fail('UNRESOLVED — ui manifests differ; the books are different capsules');\n  if (canonical(ea.code_manifest) !== canonical(eb.code_manifest))\n    return fail('UNRESOLVED — code manifests differ (different engine pins); the books are different capsules');\n  const A = ea.state, B = eb.state;\n  const chA = A.chain || [], chB = B.chain || [];\n  const rcA = A.records || [], rcB = B.records || [];\n  // --- common ancestor: longest prefix where both books agree, seals and records ---\n  let k = 0; while (k < chA.length && k < chB.length && canonical(chA[k]) === canonical(chB[k])) k++;\n  let kr = 0; while (kr < rcA.length && kr < rcB.length && canonical(rcA[kr]) === canonical(rcB[kr])) kr++;\n  if (k === 0 || kr === 0)\n    return fail('UNRESOLVED — no common ancestor: the books share no verified history; owner ruling required');\n  const baseChain = chA.slice(0, k), baseRecords = rcA.slice(0, kr);\n  const tailA_ch = chA.slice(k), tailB_ch = chB.slice(k);\n  const tailA_rc = rcA.slice(kr), tailB_rc = rcB.slice(kr);\n  const aTip = chA.length ? chA[chA.length - 1].hash : 'GENESIS';\n  const bTip = chB.length ? chB[chB.length - 1].hash : 'GENESIS';\n  const baseTip = baseChain.length ? baseChain[baseChain.length - 1].hash : 'GENESIS';\n  // --- exactly-once: a merge receipt already naming the OTHER side's tip means this pair merged ---\n  for (const [chain, otherTip, mine] of [[chA, bTip, 'A'], [chB, aTip, 'B']])\n    for (const s of chain)\n      if (s.kind === 'merge_receipt') {\n        let p = null; try { p = JSON.parse(s.payload); } catch (e) {}\n        if (p && (p.a_tip === otherTip || p.b_tip === otherTip)) {\n          const holder = mine === 'A' ? ea : eb;\n          return { ok: true, replay: true, verdict: 'VERIFIED — merge already sealed (exactly-once); the receipt naming the other tip is in the book', merge_id: p.merge_id, state: holder.state, digest: holder.digest, ui_manifest: holder.ui_manifest, code_manifest: holder.code_manifest, ui: holder.ui, code: holder.code, zero_merge: true };\n        }\n      }\n  // --- conflict scan (fork detection at merge time). Slot = (id, created).\n  // Same slot, different body = the same claimed write with different substance = CONTRADICTED,\n  // fail-closed, both books unchanged. Identical duplicates dedup. Everything else merges. ---\n  const slotMap = {};\n  const conflicts = [];\n  for (const [from, tail] of [['A', tailA_rc], ['B', tailB_rc]])\n    for (const r of tail) {\n      const key = String(r.id) + '|' + String(r.created);\n      const c = canonical(r);\n      if (slotMap[key] !== undefined && slotMap[key].canonical !== c)\n        conflicts.push({ slot: key, from1: slotMap[key].from, from2: from });\n      else if (slotMap[key] === undefined) slotMap[key] = { from, canonical: c };\n    }\n  if (conflicts.length)\n    return fail('CONTRADICTED — record slot(s) ' + conflicts.map(c => c.slot).join(', ') + ' written differently on both sides; no silent smoothing, both books unchanged, owner ruling required', { conflicts });\n  // --- deterministic order FIRST: the lexicographically smaller tip contributes first.\n  // Content decides, not seat identity, not call order. The first side keeps every record;\n  // identical duplicates are dropped from the second side only. ---\n  const aFirst = aTip < bTip;\n  const firstFrom = aFirst ? 'A' : 'B', secondFrom = aFirst ? 'B' : 'A';\n  const firstRc = aFirst ? tailA_rc : tailB_rc;\n  const secondTailRc = aFirst ? tailB_rc : tailA_rc;\n  const firstCh = aFirst ? tailA_ch : tailB_ch, secondCh = aFirst ? tailB_ch : tailA_ch;\n  const seenFirst = {}; for (const r of firstRc) seenFirst[String(r.id) + '|' + String(r.created)] = canonical(r);\n  const dedupedFromSecond = secondTailRc.filter(r => seenFirst[String(r.id) + '|' + String(r.created)] === canonical(r));\n  const secondRc = secondTailRc.filter(r => seenFirst[String(r.id) + '|' + String(r.created)] !== canonical(r));\n  // second side's records are re-ided into one numbering; originals stay verbatim in the receipt\n  const lastFirstId = firstRc.length ? Number(firstRc[firstRc.length - 1].id) : Number(baseRecords.length ? baseRecords[baseRecords.length - 1].id : 0);\n  const reIded = secondRc.map((r, j) => ({ id: lastFirstId + 1 + j, body: r.body, created: r.created }));\n  const mergedRecords = baseRecords.concat(firstRc).concat(reIded);\n  // --- the merge receipt: merge_id, tips, verdict, and the second side's divergent history verbatim (evidence, never erased) ---\n  const mergeId = await sha256hex('merge|' + baseTip + '|' + (aTip < bTip ? aTip + '|' + bTip : bTip + '|' + aTip));\n  const receipt = {\n    merge_id: mergeId, base_tip: baseTip,\n    a_tip: aTip < bTip ? aTip : bTip, b_tip: aTip < bTip ? bTip : aTip,\n    verdict: 'VERIFIED',\n    second_tail_seals: secondCh, second_records_original: secondRc, re_ided: reIded.length\n  };\n  const receiptPayload = JSON.stringify(receipt);\n  const liveTip = firstCh.length ? firstCh[firstCh.length - 1].hash : baseTip;\n  const rHash = await sha256hex(liveTip + '|merge_receipt|merge|' + receiptPayload);\n  const receiptSeal = { id: baseChain.length + firstCh.length + 1, kind: 'merge_receipt', ref: 'merge', payload: receiptPayload, prev_hash: liveTip, hash: rHash };\n  const mergedChain = baseChain.concat(firstCh).concat([receiptSeal]);\n  const newState = { records: mergedRecords, chain: mergedChain };\n  const vc = await verifyChain(mergedChain);\n  if (!vc.ok) return fail('UNRESOLVED — composed merged chain does not verify: ' + vc.issues.join('; '));\n  const digest = await digestOf(newState, uiManifest, codeManifest);\n  return {\n    ok: true, verdict: 'VERIFIED — deterministic merge complete; receipt sealed, one book, one history',\n    merge_id: mergeId, state: newState, digest, receipt: receiptSeal,\n    ingested: { records: firstRc.length + reIded.length, deduped: dedupedFromSecond.length },\n    zero_merge: false\n  };\n}\n"},"digest":null};

const BOUNDARY = {"doc":"HARZ Proof — Sealed Receipts Boundary","version":"1.0.0","date":"2026-10-02","guarantees":["Every receipt is sealed into a SHA-256 hash chain in its own D1 — rewriting any receipt, in the DB or in transit, is detectable by the public verify endpoint.","The engine exists in one canonical text, hash-pinned in the book: every verify re-derives the live functions source and byte-compares it to the sealed text (executed == sealed).","The full book exports at /api/export and verifies on any substrate with /api/source (proven third-substrate pattern).","Every receipt is cross-checked against its seal payload on each verify — a receipt rewritten in the DB is caught even if the stored digest claim is rewritten with it."],"cannot":["Hash seals prove receipts UNCHANGED, not authorship — no Ed25519 identity layer at this scale; upgrade path exists (proven in HPR v0.8+).","Delivery truth is the carrier/SendChamp claim — we seal what HARZ observed, labeled as such. A sealed lie is still a lie.","Single cloud, single D1, single writer expected at test scale: concurrent appends can race (detectable by verify, not prevented).","WRITE_KEY is a bearer secret: anyone holding it can append receipts (cannot rewrite old ones without detection).","Recipient numbers are stored masked (last-4 only) — full numbers are never sealed into the book.","No rate limits at test scale; measured at this test scale, never extrapolated."],"lockstep_limit":"A full rewrite of the ENTIRE book (records + seals + digest claim) still self-verifies — the unsolved hash-chain limit (KR3). A rewritten book has a DIFFERENT digest: anyone holding the old digest catches it. Public digest, anchors, mirrors, witness are the mitigation, same as the proven protocol.","routes":["/api/docs POST (public, 10/hr/IP at test scale, max 5MB)","/api/docs/check POST (public)","/api/doc/{seal_id} GET","/api/docs GET (recent doc seals)","/d/{seal_id} GET (seal details page)","/api/receipts POST (bearer WRITE_KEY)","/api/receipt/{hash|msg_id|id} GET","/api/verify GET","/api/export GET","/api/source GET","/boundary","/api/boundary"],"integration":"Additive only: Edge Telecom / SMPP Edge append after send/DLR via POST with the write key. The 8 telecom workers and their bindings are untouched by this build; the hook is a separate owner-approved step.","doc_seals":["Document seals prove the exact bytes existed at seal time and are unchanged; they do NOT prove authorship, legal validity, or who uploaded.","Documents are never stored: only the SHA-256 is sealed. Lose the file and the seal cannot show what it said.","AI facts are unsealed, optional annotations — informational only, can be wrong, and are NOT part of the seal.","Public document sealing is rate-limited to 10 per hour per IP at test scale.","Max 5MB per file, measured at this test scale, never extrapolated."],"v2_note":"v2.0.0 is additive: same engine (byte-identical), same book, same digest chain. UI/PWA serving bug fixed. Old book digest holders will see a new digest because the UI manifest changed — state and chain are untouched and verify."};

const E = { sha256hex, canonical, digestOf, verifyExport }; // live native engine functions
async function engineSealed() {
  if (await sha256hex(ENGINE_SRC) !== CAPSULE.code_manifest['/engine.js']) return false;
  for (const fn of [sha256hex, canonical, digestOf, verifyExport]) {
    if (!ENGINE_SRC.includes(Function.prototype.toString.call(fn))) return false;
  }
  return true;
}
async function getState(db) {
  const row = await db.prepare('SELECT state FROM book_state WHERE id=1').first();
  return row ? JSON.parse(row.state) : null;
}
async function putState(db, state, digest) {
  await db.prepare('INSERT INTO book_state (id, state, digest) VALUES (1, ?, ?) ON CONFLICT(id) DO UPDATE SET state=excluded.state, digest=excluded.digest')
    .bind(JSON.stringify(state), digest).run();
}
async function verifyBook(db) {
  const state = await getState(db);
  const book = { manifest: CAPSULE.manifest, state: state || CAPSULE.state, ui_manifest: CAPSULE.ui_manifest, ui: CAPSULE.ui, code_manifest: CAPSULE.code_manifest, code: CAPSULE.code, digest: null };
  book.digest = await E.digestOf(book.state, CAPSULE.ui_manifest, CAPSULE.code_manifest);
  let v = await E.verifyExport(book);
  // receipts hardening: every receipt must still match its sealed payload byte-for-byte
  const rcIssues = [];
  for (const sl of book.state.chain) {
    if (sl.kind !== 'record') continue;
    const rec = book.state.records[Number(sl.ref) - 1];
    if (!rec || sl.payload !== JSON.stringify(rec, ['id', 'body', 'created']))
      rcIssues.push('receipt ' + sl.ref + ' does not match its seal');
  }
  if (rcIssues.length) v = { ok: false, issues: rcIssues, verdict: 'BROKEN — ' + rcIssues.join('; '), writes: v.writes };
  return { v, book, digest: book.digest };
}
export default {
  async fetch(req, env) {
    const url = new URL(req.url), path = url.pathname, db = env.DB;
