        await putState(db, st, await E.digestOf(st, CAPSULE.ui_manifest, CAPSULE.code_manifest));
      }
      if (path === '/' || path === '/index.html') return new Response(CAPSULE.ui['/index.html'], { headers: { 'content-type': 'text/html; charset=utf-8' } });
