        if (!/^[0-9a-f]{8,64}$/i.test(qid)) return j({ ok: false, reason: 'bad seal id' }, 400);
        return new Response(CAPSULE.ui['/doc.html'], { headers: { 'content-type': 'text/html; charset=utf-8' } });
      }
      if (path === '/api/docs' && req.method === 'GET') {
        const state = await getState(db);
        const docs = [];
        for (let k = state.records.length - 1; k >= 0 && docs.length < 20; k--) {
          const r = state.records[k];
          try { const b = JSON.parse(r.body); if (b.t !== 'doc') continue; docs.push({ seal_id: null, name: b.name, size: b.size, note: b.note || '', created: r.created, record_id: r.id }); } catch (e) {}
        }
